import i18n from '~i18n'
import { baseLanguages } from '~i18n/languages'

// Generated by `pnpm og:generate` (scripts/og); one card per locale, English for anything else.
export const OPEN_GRAPH_IMAGE_WIDTH = 1200
export const OPEN_GRAPH_IMAGE_HEIGHT = 630
const fallbackLanguage = 'en'

export const getOpenGraphImagePath = (language?: string) => {
  const lang = language && language in baseLanguages ? language : fallbackLanguage
  return `/assets/og/${lang}.png`
}

// The headline printed on the card, which is what the image shows a reader. The source (en) copy
// lives in src/i18n/locales/en/common.json, next to `og.tagline`; the defaultValue is only a runtime
// fallback kept in sync with it, as in defaultHeadMeta.ts.
export const getOpenGraphImageAlt = (language?: string) =>
  i18n.t('og.headline', { lng: language, defaultValue: 'Secure online voting for your organization' })
